torch::Tensor conv_transpose3d_cuda(torch::Tensor x) {
    auto B = x.size(0);
    int C_in = x.size(1);
    int D = x.size(2);
    int H = x.size(3);
    int W = x.size(4);

    // Output spatial dimensions (naive)
    int out_D = (D + 2*padding - kernel_size) / stride + 1;
